package org.apache.lucene.rucene.codec;

import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.lucene.store.Directory;
import org.apache.lucene.store.FSDirectory;
import org.apache.lucene.store.IOContext;
import org.apache.lucene.store.IndexOutput;
import org.apache.lucene.util.IORunnable;
import org.apache.lucene.util.NumericUtils;
import org.apache.lucene.util.bkd.BKDConfig;
import org.apache.lucene.util.bkd.BKDWriter;

/**
 * Writes the BKD files of fixed scenarios through {@code BKDWriter.add} and {@code finish}, so
 * that Rucene's writer can be compared with Lucene's byte for byte.
 *
 * <p>Usage: {@code BkdWriterLayoutFixture <dir>}. For every scenario it writes {@code
 * <name>.meta}, {@code <name>.index} and {@code <name>.data}, and {@code <name>.one}, the same
 * points written through one output for the three roles. The points are generated by {@link
 * #value}, which the Rust test reproduces exactly.
 */
public final class BkdWriterLayoutFixture {

  /** One scenario: its config, heap budget and point count. */
  record Scenario(
      String name,
      int numDims,
      int numIndexDims,
      int bytesPerDim,
      int maxPointsInLeafNode,
      double maxMBSortInHeap,
      int numPoints,
      int equalDim) {}

  static final Scenario[] SCENARIOS = {
    // TestBKD.testBasicInts1D.
    new Scenario("basic1d", 1, 1, 4, 2, 1.0, 100, -1),
    // add()+finish(), small leaves, the heap writer, numDataDims > numIndexDims.
    new Scenario("heap_data_dims", 4, 2, 4, 3, 1.0, 600, -1),
    // add()+finish(), small leaves, offline sort, numDataDims > numIndexDims and one equal
    // dimension.
    new Scenario("offline_data_dims", 4, 2, 4, 3, 0.01, 2000, 1),
  };

  /**
   * The value of dimension {@code dim} of point {@code i}: a fixed mixing of the indices, with
   * a few duplicates, as unsigned big-endian bytes; {@code equalDim} is the same for every point.
   */
  static void value(Scenario s, int i, int dim, byte[] dest, int offset) {
    int v;
    if (dim == s.equalDim()) {
      v = 12345;
    } else {
      long x = (i / 3) * 0x9E3779B97F4A7C15L + dim * 0xBF58476D1CE4E5B9L;
      x ^= (x >>> 31);
      x *= 0x94D049BB133111EBL;
      x ^= (x >>> 29);
      v = (int) x;
    }
    NumericUtils.intToSortableBytes(v, dest, offset);
    for (int k = 4; k < s.bytesPerDim(); k++) {
      dest[offset + k] = (byte) (i * 31 + dim * 7 + k);
    }
  }

  public static void main(String[] args) throws Exception {
    Path path = Paths.get(args[0]);
    try (Directory dir = FSDirectory.open(path)) {
      for (Scenario s : SCENARIOS) {
        BKDConfig config =
            new BKDConfig(s.numDims(), s.numIndexDims(), s.bytesPerDim(), s.maxPointsInLeafNode());
        BKDWriter w =
            new BKDWriter(
                s.numPoints(), dir, s.name(), config, s.maxMBSortInHeap(), s.numPoints());
        byte[] packed = new byte[s.numDims() * s.bytesPerDim()];
        for (int i = 0; i < s.numPoints(); i++) {
          for (int dim = 0; dim < s.numDims(); dim++) {
            value(s, i, dim, packed, dim * s.bytesPerDim());
          }
          w.add(packed, i);
        }
        try (IndexOutput meta = dir.createOutput(s.name() + ".meta", IOContext.DEFAULT);
            IndexOutput index = dir.createOutput(s.name() + ".index", IOContext.DEFAULT);
            IndexOutput data = dir.createOutput(s.name() + ".data", IOContext.DEFAULT)) {
          IORunnable finalizer = w.finish(meta, index, data);
          finalizer.run();
        }
        w.close();

        // The same points through one output for the three roles, as TestBKD writes them:
        // `BKDWriter.writeIndex` then accounts for `metaOut == indexOut`.
        BKDWriter one =
            new BKDWriter(
                s.numPoints(), dir, s.name() + "_one", config, s.maxMBSortInHeap(), s.numPoints());
        for (int i = 0; i < s.numPoints(); i++) {
          for (int dim = 0; dim < s.numDims(); dim++) {
            value(s, i, dim, packed, dim * s.bytesPerDim());
          }
          one.add(packed, i);
        }
        try (IndexOutput out = dir.createOutput(s.name() + ".one", IOContext.DEFAULT)) {
          IORunnable finalizer = one.finish(out, out, out);
          finalizer.run();
        }
        one.close();
      }
    }
    System.out.println("write_ok=true");
  }
}
